custom_css:
/*

《 𝐒𝐀𝐓𝐈𝐒 》 作者: 睏暝@woolenbrave
此美化免費發布於旅程、尾巴鎮DC，請勿商用與二傳，二改請保留代碼作者標註。

*/

/*字體*/
@import url("https://fontsapi.zeoseven.com/79/main/result.css");
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

/* 全局 */
:root {
    /* 文字 */
    --mainfont: "Clear Han Serif"; /* 正文字體 */
    --secfont: "Noto Serif CJK";/* 裝飾字體 */
    --text-size: 1em; /*正文字體大小*/
    --text-padding: 10px; /* 正文與聊天框邊界的距離 */
    --line-height: ; /*行高*/
    --line-space: 1.3em; /*段距*/

    /* 頂欄&底欄圖標 */
    --TopBarIconColor: var(--SmartThemeUnderlineColor); /*圖標顏色*/
    --TopBarIconOpacity: 1;  /* 圖標透明度 */
    --TopBarIconSize: 18px; /*頂欄圖標大小*/
    --BottomBarIconSize: 20px; /* 底欄圖標大小 */

    /* 背景顏色 */
    --TopbarColor: var(--SmartThemeBlurTintColor); /*頂欄*/
    --BottomBarColor: var(--SmartThemeBlurTintColor); /*底欄*/
    --panel-color: var(--SmartThemeChatTintColor);/*左右欄*/
    --panel-color-phone: var(--SmartThemeBlurTintColor);/*左右欄*/

    --ButtonIconSize: 15px; /* 一般按鈕圖標大小 */

    --SmartThemeRadius: 4px;/* 全局圓角 */

    --scrollbar: 5px; /*滾動條寬度*/

    --chatborder: 0px solid  color-mix(in srgb, var(--SmartThemeBodyColor) 15%, transparent);/*聊天氣泡外框*/
    /*--TopbarBorder: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);/*頂欄底線*/ 
}

/* 🪲背景圖片 (可選)
#bg1 {
    opacity: 0.3 !important;
    filter: brightness(1) blur(0px) grayscale(0%) contrast(95%) !important;
    box-shadow: inset 0 0 100px 50px rgba(0, 0, 0, 0.0) !important;
}*/


/* 聊天訊息框模糊 (可選)
#chat {
    backdrop-filter: blur(6px) !important;
    -webkit-backdrop-filter: blur(6px) !important;
}*/

/* 🪲正文與聊天氣泡 */

 /* 對白樣式 (可選) */
.mes_text q {
  margin: 0 6px 0 0px;
  border-bottom: 1px dotted color-mix(in srgb, var(--SmartThemeQuoteColor) 100%, transparent) !important;
}

/* 聊天氣泡邊距 */
#chat {
  padding: 8px 0 8px var(--scrollbar);
}

.mes {
  margin-top: 4px;
  flex-direction: column;
  align-items: center;
  border-radius: var(--SmartThemeRadius) !important;
  padding-top: 240px !important; /*😡*/
  border: var(--chatborder) !important;
}

.mes_block {
  width: 100%;
  padding-left: 0;
}

.mes_text {
  font-size: var(--text-size);
  font-family: var(--mainfont);
  text-align: justify;
  width: 100% !important;
  line-height: var(--line-height);
  letter-spacing: 1px;
  padding: 0 var(--text-padding) 0 var(--text-padding) !important;
}

/* 段距 */
.mes_text p {
    margin-bottom: var(--line-space) !important;
}

.mes_text p:last-child {
    margin-bottom: 0px !important;
}

/* 引用塊 */
.mes_text blockquote {
  background: transparent;
  padding: 20px 20px;    
  border-radius: 10px;
  margin-bottom: 20px;
  border-left: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
  border-right: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent) !important;
  transition: border 0.6s ease, box-shadow 0.6s ease-out;
}

.mes_text blockquote:hover {
  border-left: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 100%, transparent);
  border-right: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 100%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent) !important;
}

/* 代碼包裹 by @Junezz 復古MacOs */
  code {
    background-color: transparent;
    color: var(--SmartThemeUnderlineColor);
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent) !important;
    font-size: calc(var(--mainFontSize)* 0.98);
    padding: 0px 3px;
}

/* 類名by @Junezz 復古MacOs*/
div[is_user="false"].last_mes {
  margin-bottom: 30px !important;
}

/* 類名 by @_nak.a.ri*/
#sheld::-webkit-scrollbar {
  display: none;
}

/* 聊天氣泡底端文字 */
.mes_block::after {
    content: "𖤓—⊹ 𝔐𝔢𝔪𝔢𝔫𝔱𝔬 𝔐𝔬𝔯𝔦 ⊹—𖤓";
    display: block;
    text-align: center;
    font-size: 13px;
    color: var(--SmartThemeBodyColor);
    margin-top: 20px;      
    margin-bottom: 20px;      
    opacity: 0.4;
}

/* 選取文本樣式 by@potato_juice9 */
.mes_text ::selection {
    background: var(--SmartThemeUnderlineColor) !important;
    color: var(--SmartThemeBlurTintColor);
}

/* 🪲切換消息 */
.swipeRightBlock,
.swipe_left {  
  right: calc(var(--text-padding)) !important;
  color: var(--SmartThemeUnderlineColor);
  bottom: 12px;
}

.swipe_left {
  bottom: 25px;
}

.swipe_left::before,
.swipe_right::before {
  content: ''; 
  display: inline-block;
  width: 15px;
  height: 15px; 
  background-image: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/satis/swordblack.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
}

.swipe_left::before {
  transform: rotate(-165deg);
}

.swipe_right::before {
  transform: rotate(85deg);
}

/*🪲頭像*/

body.square-avatars .avatar, body.square-avatars .mes .avatar img {
    border-radius: 50% !important;
}

body.square-avatars .avatar, body.square-avatars .avatar img {
  border-radius: var(--SmartThemeRadius) !important;
}

.avatar img {
    box-shadow: 0 4px 8px rgba(0,0,0,0.6) !important;
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent);
}

.mes .avatar {
    position: absolute !important;
    left: 50% !important;
    top: -160px !important; /*😡*/
}

/* 聊天訊息頭像 */
.mes .avatar img {
    position: absolute;
    height: 101px !important;
    width: 85px !important;
    border-radius: 50% !important; 
    border: 4px double color-mix(in srgb, var(--SmartThemeBodyColor) 90%, transparent) !important; 
    box-shadow: 0 4px 8px rgba(0,0,0,0.6) !important;
    padding: 2px !important;
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent) !important;5
    object-fit: cover !important;
    transform: translateX(-50%);
    transition: transform 0.6s ease-out, box-shadow 0.6s ease-out !important;
    z-index: 10 !important;
}

.mes .avatar img:hover {
    transform: translateX(-50%) translateY(-8px) !important;
    box-shadow: 0 10px 16px rgba(0,0,0,0.6) !important;
}

.mesAvatarWrapper {
  position: static !important;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.mes .avatar {
    position: relative !important;
}

/* 皇冠頭像裝飾 */
.mes .avatar::after {
    content: "";
    display: block;
    background-image: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/satis/crownblack.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;   
    width: 100px;
    height: 43px;
    position: absolute;
    top: -34px;  
    transform: translateX(-50%);
    z-index: 0 !important;
    pointer-events: none;
    transition: transform 0.6s ease-out !important; 
}

.mes .avatar:hover::after {
    transform: translateX(-50%) translateY(-8px) !important;
}

/*🪲聊天氣泡頂部元素*/

.mes_buttons, .mes_edit_buttons, .mes_ghost, .mes .name_text, .mesIDDisplay, .mes_timer,
.tokenCounterDisplay,.icon-svg,.timestamp {
  color: var(--SmartThemeBodyColor);
  position: absolute !important;
  z-index: 20  !important;
}

/* 🍺角色名字 */
.mes .name_text {
  top: 198px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 16.5px;
  font-family: var(--secfont);
  opacity: 0.9;
}

.mes .name_text::before {
  content: "-";
  margin-right: 8px;
  display: inline-block;
  transform: scaleX(-1) translateY(-3px);
  opacity: 0.7;
}

.mes .name_text::after {
  content: "-";
  margin-left: 8px;
  display: inline-block;
  transform: translateY(-3px);
  opacity: 0.7;
}

/* 🍺日期時間 */
.timestamp {
    top: 218px;
    font-size: 12px;
    transform: translateX(-50%);
    left: 50%;
}

/* 🍺小鉛筆 */
.mes_buttons {
    top: 15px !important;
    right: var(--text-padding);
}

/* 類名 by @_nak.a.ri*/
.mes_button, .extraMesButtons>div, .mes_buttons .fa-solid,
 .mes_edit_buttons .fa-solid {
    color: var(--SmartThemeBodyColor) !important;
    filter: none;
}

/*小鉛筆圖標透明度*/
.mes_button, .extraMesButtons>div, .favorite-toggle-icon, .mes_reasoning_actions .edit_button {
  opacity: 0.35;
}

.mes_edit_buttons .menu_button {opacity: 0.6;}

.mes_edit::before { 
  content: "\f56b";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900;
}

.extraMesButtonsHint::before {   
  content: "\f518";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900; 
}

.extraMesButtonsHint {
  padding-right: 8px;
}

/* 🍺正文edit按键 */
.mes_edit_buttons {
    top: 12px !important;
    right: 14px;
    padding: 0;
    filter: none;
}

/* 🍺幽靈圖標 */
.mes_ghost {
    top: 55px; 
    right: calc(var(--text-padding) + 6px);
    opacity: 0.35;
}

.mes_buttons:hover, .mes_edit_buttons:hover, .mes_button:hover,.mes_ghost:hover, .mes .name_text:hover, .timestamp:hover {
  opacity: 1 !important;
  text-shadow: 0 0 16px color-mix(in srgb, var(--SmartThemeBodyColor) 100%, transparent) !important;
}

/* 🍺訊息編號 */
.mesIDDisplay {
  top: 15px;
  font-size: 18px !important;
}

.mesIDDisplay::before {
  content: "Ch";
  margin-right: 8px;
  font-size: 16.5px !important;
}

/* 🍺Token */
.tokenCounterDisplay { 
  top: 46px;
  font-size: 13px !important;
}

.tokenCounterDisplay::before {
  content: "Tokens";
  margin-right: 8px;
  font-size: 11.5px !important;
}

/* 🍺計時 */
.mes_timer {
  top: 71px ;
  font-size: 13px;
}

.mes_timer::before {
  content: "Time";
  margin-right: 8px;
  font-size: 11.5px !important;
}

.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    left: var(--text-padding);
}

/* 🪲小冰塊動畫 */
.timestamp, .mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    padding: 3px 10px;
    opacity: 0.65 !important;
    transition: border 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.6s ease-out;
    font-family: var(--secfont);
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 0%, transparent);
}

.mes_timer:hover, .tokenCounterDisplay:hover, .mesIDDisplay:hover {
  opacity: 1 !important;
  border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 40%, transparent);
  box-shadow: inset 0 0 5px color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent) !important;
}

.mes_timer:hover, .tokenCounterDisplay:hover, .mesIDDisplay:hover {
  transform: translateX(8px);
}

/*🪲左右欄*/
#right-nav-panel, #left-nav-panel {
    background-color: var(--panel-color) !important;
    border: none;
}

/* 手機端左右欄背景顏色 */
@media screen and (max-width: 768px) {
  #left-nav-panel, 
  #right-nav-panel {
    background-color: var(--panel-color-phone) !important; 
  }
}

/* PC端左右欄佔滿全屏 */
@media screen and (min-width: 1025px) and (pointer: fine) {
  #left-nav-panel, 
  #right-nav-panel {
    top: 0 !important;
    height: 100vh !important;
    max-height: 100vh !important;
  }
}

/*右欄角色管理*/
.bogus_folder_select:hover, .character_select:hover {
    background-color: transparent; 
    box-shadow: inset 0 0 8px var(--SmartThemeBodyColor);
    border-radius: var(--SmartThemeRadius);
}

.bogus_folder_select, .character_select {padding: 8px;}

#rm_button_characters, #rm_button_panel_pin_div, #lm_button_panel_pin_div, #WI_button_panel_pin_div {
    font-size: 1.15em !important;
    opacity:  1;
    padding-bottom: 5px;
}

/* 角色收藏 */
.hotswap.avatars_inline {
    display: flex;
    flex-wrap: wrap;
    transition: all 1s ease;
    scrollbar-width: none;
}

.hotswap.avatars_inline::-webkit-scrollbar {
    display: none;
}

.hotswap.avatars_inline:hover {
    max-height: 300px;
    overflow: auto;
}

/*收藏角色頭像框 by @rech0_viixi 雙色盒子*/
.character_select.is_fav .avatar {
  outline: 4px double var(--SmartThemeUnderlineColor);
  border-radius: 2px !important;
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeBodyColor);
}

/*🪲思維鏈*/

/* 思維鏈容器 */
.mes_reasoning_details {
    margin-left: var(--text-padding);
    margin-right: var(--text-padding);
}

/* 標題區域 */
.mes_reasoning_header {
    position: relative;
    left: calc(50% - 19px);
    top: 12px; /*😡*/
    transform: none; 
    display: flex;
    height: 50px;
    background-color: transparent;
    font-size: 0 !important;
    z-index: 20;
    margin-bottom: 0px;
}

/* 思維鏈標題裝飾圖片 */
.mes_reasoning_header::before {
    content: '';
    position: absolute; 
    top: 0;
    left: 0;
    transform: translate(-50%, -50%);
    width: 230px;
    height: 50px; 
    background: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/satis/Rblack.png') no-repeat center;
    background-size: contain;
    z-index: 20;
}

.mes_reasoning_header:hover {
      transition: filter 0.6s ease;
}

.mes_reasoning_header:hover {
  filter: drop-shadow(0 0 5px var(--SmartThemeBodyColor)) !important;
}

/* 思維鏈內容主體 */
.mes_reasoning {
    max-height: 480px; /* 思維鏈內容開啟高度 */
    overflow-y: auto;
    overflow-x: hidden;
    color: var(--SmartThemeBodyColor) !important;
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent);
    border: 1px dotted color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent);
    margin-bottom: 18px;
}

/* 隱藏原始箭頭 */
.mes_reasoning_details .mes_reasoning_arrow {
    display: none !important;
}

.mes_reasoning_header_block {
    margin: 0;
}

.reasoning_edit_textarea, .edit_textarea {
  margin-bottom: 15px;
}

/* 🪲圓角樣式 */
.drawer-content, 
.popup, 
.mes_block, 
.text_pole, 
textarea, 
select,
#send_form,
.inline-drawer-toggle,
.menu_button,
.bg_tab_panel,
input[type='checkbox'] {
    border-radius: var(--SmartThemeRadius) !important;
}

/* 🪲去除陰影 */
body, #sheld,
.drawer-content, 
.popup, 
#send_form, 
.mes_block, 
.menu_button, 
.text_pole, 
#top-bar, 
.inline-drawer-toggle,
input[type='checkbox'] {
    box-shadow: none !important;
}

/* 🪲圓角 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader
 {
    background-image: none;
    border-radius: var(--SmartThemeRadius);
    margin-bottom: 5px;
}

/* 🪲標題 by @rech0_viixi 雙色盒子*/
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content > h3,
.drawer-content
  .flex-container
  h3:first-of-type:not(#Backgrounds .textAlignCenter),
.drawer-content .flex-container .flex-container h3:first-of-type,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.2);
  font-weight: 600;
  letter-spacing: 0.1em;
  white-space: nowrap;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content > h3::before,
.drawer-content
  .flex-container
  h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
.drawer-content .flex-container .flex-container h3:first-of-type::before,
.popup h3:not(dialog *)::before {
  content: "⚜";
  position: relative;
  -webkit-background-clip: text;
  background-clip: text;
  font-size: calc(var(--mainFontSize) * 1.3);
  text-shadow: none;
  padding-right: 2px;
  color: var(--SmartThemeUnderlineColor);
  top: -1px;
}

/* 修正标题没对齐的问题 */
.drawer-content .alignItemsBaseline {
  align-items: center !important;
}

/*🪲抽屜*/
.drawer-content {
    border-radius: 0px !important;
    padding: 12px;
    border-bottom: 3px double color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
}

/*抽屜彈窗*/
.popup {
    box-shadow: transparent !important;
    padding: 1px;
}

@media (max-width: 768px) { 
.popup {     
    max-width: 95% !important;     
  } 
}

/* 🪲彈窗按鈕布局 改自@haha1jianghuguan */
.popup .popup-controls,
#extensions_modal .popup-controls,
.extension_install_button_container {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: stretch;
    gap: 8px;
    width: 100%;
    padding: 0 8px;
    box-sizing: border-box;
}

.popup .popup-controls .menu_button,
.popup .popup-controls > div,
.extension_install_button_container .menu_button {
    flex: 1 1 0;
    min-width: 0;
    margin-top: 0 !important;
    height: 2em !important;
    font-size: 13px !important;
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
}

.popup .popup-controls .menu_button {
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent) !important;
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent) !important;
    padding: 10px !important;
}

/* 彈窗按鈕樣式 */
.popup .popup-controls .menu_button {
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent) !important;
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent) !important;
    padding: 10px !important;
}

/* 🪲輸入框 */
.range-block-counter input, textarea, .text_pole {
    background-color: transparent !important;
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 15%, transparent);
    transition: box-shadow 0.3s ease-out, border 0.3s ease-out; 
}

.range-block-counter input:hover, .text_pole:hover, .range-block-counter input:focus, .text_pole:hover, .text_pole:focus, textarea:focus, textarea:hover {
    box-shadow: inset 0 0 10px color-mix(in srgb, var(--SmartThemeBodyColor) 25%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 50%, transparent);
}

textarea {
    padding: 4px 8px !important;
}

/*🪲下拉框按鈕*/
select {
    background-color: transparent !important;
    border: 1px solid color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent) !important;
    border-radius: var(--SmartThemeRadius);
    margin-bottom: 5px !important;
    padding-left: 7px;
}

select:hover {
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 6%, transparent) !important;
}

/* 下拉按鈕圖標 */
.custom-drawer-icon, .inline-drawer-icon {
    font-size: calc(var(--ButtonIconSize) * 0.98);
    filter: none;
}

/*滑動條背景*/
.neo-range-input {
    background-color: transparent;
}

/* 滑動條 by @_nak.a.ri */
input[type="range"], input[type="range"]:disabled {
  filter: none;
  box-shadow: none !important;
  background-color: color-mix(in srgb, var(--SmartThemeUnderlineColor) 60%, transparent) !important;
  height: 4px !important;
  border-radius: 5px !important;
}

input[type="range"]::-webkit-slider-thumb {
  border: none;
  cursor: pointer;
  background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);
  box-shadow: none;
  width: 10px;
  height: 10px;
}

/* 🪲按鈕樣式 */
.menu_button, 
.right_menu_button, 
.mes_button, 
.drawer-icon {
    filter: none;
    background-color: transparent !important;
    border-color: transparent !important;
    color: var(--SmartThemeUnderlineColor) !important;
    font-size: var(--ButtonIconSize) !important;
    transition: background-color 0.2s ease, opacity 0.2s ease !important;
}

/* 按鈕懸停 */
.menu_button:hover, 
.right_menu_button:hover, 
.mes_button:hover, 
.drawer-icon:hover {
    opacity: 0.6 !important;
}

